import { Controller } from "@hotwired/stimulus"
import { FetchRequest } from "@rails/request.js"

export default class extends Controller {
  static targets = ["details"]
  static values = {
    subscribeUrl: String,
    unsubscribeUrl: String,
    vapidPublicKey: String
  }

  async connect() {
    this.subscription = await this.#subscription()
    this.#sync()
  }

  toggle() {
    if (this.subscription) {
      this.#turnOff()
    } else {
      this.#turnOn()
    }
  }

  // private

  async #sync() {
    const on = this.subscription != null && Notification.permission === "granted"
    this.element.classList.toggle("notifications--on", on)
    this.element.classList.toggle("notifications--off", !on)

    const blocked = Notification.permission === "denied"
    this.detailsTargets.forEach((target) => target.hidden = !blocked)
  }

  #turnOn() {
    Notification.requestPermission().then((permission) => {
      if (permission === "granted") {
        this.#subscribe().then(() => this.#sync())
      } else {
        this.#sync()
      }
    })
  }

  async #turnOff() {
    if (this.subscription) {
      await this.#delete(this.unsubscribeUrlValue, { endpoint: this.subscription.endpoint })
      await this.subscription.unsubscribe().catch(() => {})
      this.subscription = null
      this.#sync()
    }
  }

  async #subscribe() {
    const registration = await navigator.serviceWorker.ready
    this.subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: this.#applicationServerKey
    })
    await this.#post(this.subscribeUrlValue, this.#subscriptionParams)
  }

  get #subscriptionParams() {
    const { endpoint, keys } = this.subscription.toJSON()
    return { endpoint: endpoint, p256dh_key: keys.p256dh, auth_key: keys.auth }
  }

  async #subscription() {
    if (!this.#supported) return null
    const registration = await navigator.serviceWorker.ready
    return registration.pushManager.getSubscription()
  }

  get #supported() {
    return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window
  }

  get #applicationServerKey() {
